use nms_core::{address::GalacticAddress,system::System};
use nms_graph::{GalaxyModel,SystemId};
use std::collections::HashSet;
fn capped(m:&GalaxyModel,s:SystemId,r:f64)->usize{
 let mut seen=HashSet::from([s]);let mut todo=vec![s];
 while let Some(current)=todo.pop(){let a=m.system(current).unwrap().address;
  for (id,d) in m.nearest_systems_from_address(&a,100){if d<=r && seen.insert(id){todo.push(id);}}
 } seen.len()
}
fn main(){
 for dense in [false,true]{
 let mut m=GalaxyModel::new();let mut all=HashSet::new();
 for n in 0..120u16 {let a=if dense{GalacticAddress::new(0,0,0,n+1,0,9)}else{GalacticAddress::new(n as i16,0,0,1000+n,0,9)};all.insert(SystemId::from_address(&a));m.insert_system(System::new(a,None,None,None,vec![]));}
 let a=if dense{GalacticAddress::new(0,0,0,1,0,9)}else{GalacticAddress::new(0,0,0,1000,0,9)};let s=SystemId::from_address(&a);let r=if dense{1000.0}else{47600.0};
 let got=m.reachable_systems(s,r).unwrap().into_iter().collect::<HashSet<_>>();assert_eq!(got,all);
 println!("dense={dense} actual={} nearest100_negative_control={}",got.len(),capped(&m,s,r));
 }
 let mut m=GalaxyModel::new();let left=GalacticAddress::new(-1,0,0,2,0,0);let right=GalacticAddress::new(1,0,0,9,0,0);
 for (a,name) in [(left,"Zulu"),(right,"Alpha")]{m.insert_system(System::new(a,Some(name.into()),None,None,vec![]));}
 let got=m.nearest_systems_from_address(&GalacticAddress::new(0,0,0,1,0,0),usize::MAX);assert_eq!(got,vec![(SystemId::from_address(&left),400.0),(SystemId::from_address(&right),400.0)]);println!("literal_numeric_tie={got:?}");
}

